from pathlib import Path
p=Path('games/wip/index.html')
s=p.read_text()
css='''
:root{--top:max(10px,env(safe-area-inset-top));--bot:max(10px,env(safe-area-inset-bottom));--bg:#09101b;--ink:#eef8ff;--muted:#a0b2c4;--panel:#111a29;--panel2:#0a1220;--line:#35506e;--line2:#1e3148;--cyan:#73dcff;--gold:#ffd36e;--pink:#ff8fb3;--green:#8ef0a7;--purple:#b29cff;--danger:#ff7a84}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none;touch-action:none}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--ink);font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;image-rendering:pixelated}
body{position:fixed;inset:0}#app{position:fixed;inset:0;display:flex;flex-direction:column;background:radial-gradient(circle at 50% 0,#183557,#0b1322 48%,#060b12)}
#hud{padding:var(--top) 8px 6px;display:grid;grid-template-columns:1.25fr 1fr;gap:7px}.panel{position:relative;background:linear-gradient(#152238,#0d1423);border:2px solid var(--line);padding:8px 8px 7px;box-shadow:inset 0 0 0 2px #0a1220,inset 0 -4px 0 #0b1220,0 3px 0 #08101b}.panel:before,.panel:after{content:"";position:absolute;width:6px;height:6px;background:#09101b;top:-2px;border-top:2px solid var(--line)}.panel:before{left:-2px;border-left:2px solid var(--line)}.panel:after{right:-2px;border-right:2px solid var(--line)}
.r{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:9px;line-height:1.4}.r b{font-size:10px;letter-spacing:.06em}.bar{height:10px;background:#09101b;border:2px solid #253b55;overflow:hidden;margin-top:4px;box-shadow:inset 0 2px 0 #0008}.fill{height:100%;background:repeating-linear-gradient(90deg,var(--green) 0 10px,#73c98a 10px 12px);transition:width .18s}.enemy{background:repeating-linear-gradient(90deg,var(--pink) 0 10px,#ff709a 10px 12px)}
#stage{position:relative;flex:1;min-height:0;margin:0 7px 6px;border:2px solid var(--line);overflow:hidden;background:linear-gradient(#0a1320,#0d1826 65%,#09101a);box-shadow:inset 0 0 0 2px #08101b,0 4px 0 #060b12}#stage:before{content:"";position:absolute;inset:0;pointer-events:none;background:linear-gradient(rgba(255,255,255,.025) 50%,rgba(0,0,0,.04) 50%);background-size:100% 4px;mix-blend-mode:screen;opacity:.45}canvas{position:absolute;inset:0;width:100%;height:100%}#problem{position:absolute;left:10px;right:10px;top:10px;text-align:center;font-weight:1000;font-size:18px;letter-spacing:.5px;text-shadow:0 2px 0 #000,0 0 10px #000}#hint{position:absolute;left:8px;right:8px;bottom:8px;text-align:center;font-size:9px;color:#d4e3ef;background:linear-gradient(#07111d,#0b1421);border:2px solid var(--line2);padding:7px;box-shadow:inset 0 0 0 2px #09101b}
#board{padding:0 8px 8px;display:grid;grid-template-columns:1fr 1fr;gap:7px}.term,.ctrl,.bigbtn,.choice{position:relative;overflow:hidden}.term{min-height:68px;border:2px solid #4a6c8d;background:linear-gradient(#1c3044,#122031);color:var(--ink);font:900 11px ui-monospace,monospace;padding:8px;text-align:left;box-shadow:inset 0 0 0 2px #0a1321,inset 0 -4px 0 #0e1826,0 3px 0 #09111b}.term:after,.ctrl:after,.bigbtn:after,.choice:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(255,255,255,.08),rgba(255,255,255,0) 30%,rgba(0,0,0,.08));pointer-events:none}.term small{display:block;color:var(--muted);font-size:8px;margin-top:4px}.term strong{font-size:16px}.term.done{border-color:#6ddc98;background:linear-gradient(#1c3b36,#112621)}.term.lock{opacity:.45}.term.wrong{animation:shake .22s linear}.term:active{transform:translateY(2px);box-shadow:inset 0 0 0 2px #0a1321,inset 0 -2px 0 #0e1826,0 1px 0 #09111b}@keyframes shake{25%{transform:translateX(-4px)}75%{transform:translateX(4px)}}
#controls{padding:0 8px var(--bot);display:grid;grid-template-columns:1fr 1fr;gap:7px}.ctrl{min-height:50px;border:2px solid #4a6c8d;background:linear-gradient(#27415d,#17283b);color:var(--ink);font:1000 10px ui-monospace,monospace;box-shadow:inset 0 0 0 2px #0a1321,inset 0 -4px 0 #101b29,0 3px 0 #09111b}.ctrl.primary{background:linear-gradient(#5f4c29,#2c2415);border-color:#967d47}.ctrl.ready{box-shadow:0 0 0 2px #ffd36e66,inset 0 0 0 2px #0a1321,inset 0 -4px 0 #101b29,0 0 16px #ffd36e33,0 3px 0 #09111b}.ctrl:active{transform:translateY(2px);box-shadow:inset 0 0 0 2px #0a1321,inset 0 -2px 0 #101b29,0 1px 0 #09111b}
#start,.modal{position:fixed;inset:0;z-index:20;background:#03070def;display:none;align-items:center;justify-content:center;padding:calc(var(--top) + 12px) 12px calc(var(--bot) + 12px)}#start{display:flex}.modal.on{display:flex}.card{width:min(94vw,560px);max-height:calc(100dvh - var(--top) - var(--bot) - 24px);overflow:auto;touch-action:pan-y;background:linear-gradient(#152238,#0c1422);border:2px solid #476482;box-shadow:inset 0 0 0 2px #0a1220,0 4px 0 #09111b;padding:15px}.card h1,.card h2{margin:0 0 8px}.small{font-size:10px;color:#afc0d2;line-height:1.55}.legend{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:10px}.legend div{background:#09111c;border:2px solid #26394f;padding:9px;font-size:8px;line-height:1.4}.bigbtn{width:100%;margin-top:10px;padding:12px;border:2px solid #5f6f87;background:linear-gradient(#33465f,#233246);color:#fff;font:1000 10px ui-monospace,monospace;box-shadow:inset 0 0 0 2px #101925,inset 0 -4px 0 #1b2634,0 3px 0 #09111b}.bigbtn:active,.choice:active{transform:translateY(2px)}.choice{width:100%;text-align:left;margin-top:7px;padding:10px;border:2px solid #3b5875;background:linear-gradient(#1a2d42,#122031);color:#fff;font:900 10px ui-monospace,monospace;box-shadow:inset 0 0 0 2px #0b1220,inset 0 -4px 0 #101a28,0 3px 0 #09111b}.choice span{display:block;color:#afc0d2;font-size:9px;margin-top:4px}.flash{position:absolute;inset:0;pointer-events:none;background:#fff0}.flash.on{animation:flash .18s linear}@keyframes flash{50%{background:#fff3}}@media(min-width:700px){#app{max-width:620px;left:50%;transform:translateX(-50%);border-left:2px solid #1b2c3e;border-right:2px solid #1b2c3e}}
'''
a=s.index('<style>')+7;b=s.index('</style>');s=s[:a]+css+s[b:]
s=s.replace('comboBurst:0,deck:[]};','comboBurst:0,deck:[],shake:0,ambientT:0};')
s=s.replace("function particles(px,py,n=16){for(let i=0;i<n;i++)S.particles.push({x:px,y:py,vx:(Math.random()-.5)*160,vy:(Math.random()-.5)*160,t:.6})}","function particles(px,py,n=16,opt={}){let c=opt.color||'#ffd36e',size=opt.size||4,spread=opt.spread||160,life=opt.life||.6,grav=opt.gravity||0,shape=opt.shape||'square';for(let i=0;i<n;i++)S.particles.push({x:px,y:py,vx:(Math.random()-.5)*spread,vy:(Math.random()-.5)*spread,t:life,life,color:c,size:size+(Math.random()<.3?1:0),gravity:grav,shape})}")
s=s.replace("function flash(){let f=document.getElementById('flash');f.classList.remove('on');void f.offsetWidth;f.classList.add('on')}","function textBurst(text,px,py,color='#eef8ff'){S.particles.push({x:px,y:py,vx:0,vy:-25,t:.8,life:.8,color,size:1,shape:'text',text})}\nfunction flash(){let f=document.getElementById('flash');f.classList.remove('on');void f.offsetWidth;f.classList.add('on')}")
old="function answerTerm(i,v,ans){if(v===ans){S.solved[i]=true;S.lastPart=i;S.streak++;let dmg=14+Math.min(18,S.streak*2);S.enemy=Math.max(1,S.enemy-dmg);tone(640,.08,.025,'triangle');spawnBeam(i,false);particles(W*.5,H*.48,12);flash();setHint('Correct. '+S.parts[i][0]+' × '+S.parts[i][1]+' = '+ans+'. '+(S.solved.every(Boolean)?'All sectors charged. COMBINE them.':'That sector hit the target. Keep the chain alive and charge another.'))}else{S.hp--;S.streak=0;tone(110,.12,.025,'sawtooth');terms[i].classList.add('wrong');setTimeout(()=>terms[i].classList.remove('wrong'),240);setHint('Not quite. Break it smaller if needed. Example: 40 × 20 = 4 × 2 × 100.');if(S.hp<=0){S.hp=2;setHint('Core rebooted. The grid stays intact, so you can keep learning this problem.')}}renderUI()}"
new="function answerTerm(i,v,ans){if(v===ans){S.solved[i]=true;S.lastPart=i;S.streak++;let dmg=14+Math.min(18,S.streak*2);S.enemy=Math.max(1,S.enemy-dmg);tone(640,.08,.025,'triangle');spawnBeam(i,false);let g=gridGeom(),r=g.rects[i],sx=r.x+r.w/2,sy=r.y+r.h/2;particles(sx,sy,14,{color:['#73dcff','#ffd36e','#ff8fb3','#b29cff'][i],size:4,spread:140,life:.62});particles(W*.5,H*.48,12,{color:'#ffd36e',size:4,spread:170,life:.58});textBurst('+'+ans,sx,sy,'#eef8ff');S.shake=Math.max(S.shake,.28);flash();setHint('Correct. '+S.parts[i][0]+' × '+S.parts[i][1]+' = '+ans+'. '+(S.solved.every(Boolean)?'All sectors charged. COMBINE them.':'That sector hit the target. Keep the chain alive and charge another.'))}else{S.hp--;S.streak=0;tone(110,.12,.025,'sawtooth');terms[i].classList.add('wrong');particles(W*.5,H*.48,10,{color:'#ff7a84',size:3,spread:120,life:.5});textBurst('MISS',W*.5,H*.41,'#ff8fb3');S.shake=Math.max(S.shake,.18);setTimeout(()=>terms[i].classList.remove('wrong'),240);setHint('Not quite. Break it smaller if needed. Example: 40 × 20 = 4 × 2 × 100.');if(S.hp<=0){S.hp=2;setHint('Core rebooted. The grid stays intact, so you can keep learning this problem.')}}renderUI()}"
s=s.replace(old,new)
old="function answerTotal(v,ans,vals){if(v===ans){S.enemy=0;S.streak+=2;S.combineFlash=1.1;spawnBeam(0,true);spawnBeam(1,true);spawnBeam(2,true);spawnBeam(3,true);tone(130,.12,.03,'sawtooth');setTimeout(()=>tone(520,.18,.025,'triangle'),60);particles(W*.5,H*.42,34);flash();setHint(vals.join(' + ')+' = '+ans+'. The whole grid fires at once!');renderUI();setTimeout(()=>{S.node++;S.hp=Math.min(S.mhp,S.hp+1);makeProblem()},950)}else{S.hp--;S.streak=0;tone(95,.15,.03);setHint('Check the final addition: '+vals.join(' + ')+'. The decomposition is right, so only the recombination needs fixing.');if(S.hp<=0)S.hp=2;renderUI()}}"
new="function answerTotal(v,ans,vals){if(v===ans){S.enemy=0;S.streak+=2;S.combineFlash=1.1;spawnBeam(0,true);spawnBeam(1,true);spawnBeam(2,true);spawnBeam(3,true);tone(130,.12,.03,'sawtooth');setTimeout(()=>tone(520,.18,.025,'triangle'),60);particles(W*.5,H*.42,40,{color:'#ffd36e',size:5,spread:220,life:.9});particles(W*.5,H*.42,22,{color:'#73dcff',size:4,spread:180,life:.75});textBurst('TOTAL '+ans,W*.5,H*.36,'#ffd36e');S.shake=Math.max(S.shake,.42);flash();setHint(vals.join(' + ')+' = '+ans+'. The whole grid fires at once!');renderUI();setTimeout(()=>{S.node++;S.hp=Math.min(S.mhp,S.hp+1);makeProblem()},950)}else{S.hp--;S.streak=0;tone(95,.15,.03);particles(W*.5,H*.44,8,{color:'#ff7a84',size:3,spread:110,life:.45});setHint('Check the final addition: '+vals.join(' + ')+'. The decomposition is right, so only the recombination needs fixing.');if(S.hp<=0)S.hp=2;renderUI()}}"
s=s.replace(old,new)
s=s.replace("function draw(){x.clearRect(0,0,W,H);let t=performance.now()/1000,cx=W*.5,cy=H*.47,g=gridGeom();","function draw(){x.clearRect(0,0,W,H);let t=performance.now()/1000,cx=W*.5,cy=H*.47,g=gridGeom();if(S.shake>0)S.shake=Math.max(0,S.shake-1/30);let sx=S.shake?Math.round((Math.random()-.5)*10*S.shake):0,sy=S.shake?Math.round((Math.random()-.5)*10*S.shake):0;x.save();x.translate(sx,sy);S.ambientT+=1/60;if(S.ambientT>.12){S.ambientT=0;particles(18+Math.random()*(W-36),58+Math.random()*(H-140),1,{color:Math.random()<.65?'#73dcff':'#ffd36e',size:2,spread:24,life:1.1,gravity:-4})}")
s=s.replace("for(const q of S.particles){q.t-=1/60;q.x+=q.vx/60;q.y+=q.vy/60;x.globalAlpha=clamp(q.t*2,0,1);x.fillStyle='#ffd36e';x.fillRect(Math.round(q.x),Math.round(q.y),4,4)}S.particles=S.particles.filter(q=>q.t>0);x.globalAlpha=1;x.textAlign='left';requestAnimationFrame(draw)","for(const q of S.particles){q.t-=1/60;q.x+=q.vx/60;q.y+=q.vy/60;q.vy+=(q.gravity||0)/60;x.globalAlpha=clamp(q.t/(q.life||1)*1.3,0,1);x.fillStyle=q.color||'#ffd36e';if(q.shape==='text'){x.font='900 10px monospace';x.textAlign='center';x.fillText(q.text,Math.round(q.x),Math.round(q.y))}else{x.fillRect(Math.round(q.x),Math.round(q.y),(q.size||4),(q.size||4))}}S.particles=S.particles.filter(q=>q.t>0);x.globalAlpha=1;x.restore();x.textAlign='left';requestAnimationFrame(draw)")
